<template><DetailSection :title="title"><FieldRow label="证件类型" :value="typeName"/><FieldRow label="姓名" :value="value.name"/><FieldRow label="号码（受保护）" :value="protectedFields[prefix+'.number']||'未提供'"/><FieldRow label="地址（受保护）" :value="protectedFields[prefix+'.address']||'未提供'"/><FieldRow label="有效期开始" :value="value.validFrom"/><FieldRow label="有效期截止" :value="value.longTerm?'长期有效':value.validThrough"/><FieldRow label="证件材料" wide><AttachmentList :value="[value.frontFileId,value.backFileId].filter(Boolean)" purpose="CHANNEL"/></FieldRow></DetailSection></template>
